import{_ as r,c as e,o as d,at as o}from"./chunks/framework.mXguc-v6.js";const u=JSON.parse('{"title":"React 术语速查","description":"","frontmatter":{},"headers":[],"relativePath":"views/interview/frontend/react/glossary.md","filePath":"views/interview/frontend/react/glossary.md","lastUpdated":null}'),s={name:"views/interview/frontend/react/glossary.md"};function n(a,t,g,i,c,l){return d(),e("div",null,t[0]||(t[0]=[o('<h1 id="react-术语速查" tabindex="-1">React 术语速查 <a class="header-anchor" href="#react-术语速查" aria-label="Permalink to &quot;React 术语速查&quot;">​</a></h1><table tabindex="0"><thead><tr><th>术语</th><th>一句话</th></tr></thead><tbody><tr><td><strong>Fiber</strong></td><td>React 16 的协调引擎，每个组件对应一个 JS 对象，可中断、可分片</td></tr><tr><td><strong>Hooks</strong></td><td>useState/useEffect 等函数，在 Fiber.memoizedState 上挂成链表</td></tr><tr><td><strong>Virtual DOM</strong></td><td>JS 对象描述真实 DOM，diff 后批量更新</td></tr><tr><td><strong>Reconciliation</strong></td><td>协调——对比新旧 VNode 决定怎么更新 DOM</td></tr><tr><td><strong>Concurrent Mode</strong></td><td>可中断渲染，高优任务能插队</td></tr><tr><td><strong>Time Slicing</strong></td><td>渲染任务切成 5ms 小块</td></tr><tr><td><strong>Double Buffering</strong></td><td>current ↔ workInProgress 两棵树切换</td></tr><tr><td><strong>Suspense</strong></td><td>声明式加载状态，fallback 自动显示</td></tr><tr><td><strong>RSC</strong></td><td>Server Components，零 JS 到客户端</td></tr><tr><td><strong>SSR</strong></td><td>服务端生成 HTML 加速首屏</td></tr><tr><td><strong>memo</strong></td><td><code>React.memo(Comp)</code>，props 不变跳过渲染</td></tr><tr><td><strong>useCallback</strong></td><td>缓存函数引用，配合 memo 用</td></tr><tr><td><strong>useMemo</strong></td><td>缓存计算结果</td></tr><tr><td><strong>useRef</strong></td><td>跨渲染保留可变对象，不触发重渲染</td></tr><tr><td><strong>Closure Trap</strong></td><td>闭包捕获旧值——useEffect/setTimeout 读到的是创建时的 state</td></tr><tr><td><strong>Functional Update</strong></td><td><code>setState(prev =&gt; newState)</code> 永远读到最新值</td></tr><tr><td><strong>Derived State</strong></td><td>派生状态，完全由已有 state 计算得出</td></tr><tr><td><strong>Lifting State Up</strong></td><td>状态提升到最近的共同父组件</td></tr><tr><td><strong>Immutability</strong></td><td>不可变数据，引用变化驱动渲染</td></tr></tbody></table>',2)]))}const f=r(s,[["render",n]]);export{u as __pageData,f as default};
